import{_ as o,o as t,c as a,ag as n}from"./chunks/framework.CukOUUOK.js";const u=JSON.parse('{"title":"鹅城再收一轮税——房产税落地如何重塑中美房产配置策略（下）","description":"一、基准线：中美持有成本的落差有多大？ 在讨论”冲击”之前，必须先确认一个事实——当前中美房产持有成本的差距，不是百分之几的差距，而是数量级的差距。 以一套价值50万美元（约360万人民币）的房产为例： 持有成本项美国（…","frontmatter":{"title":"鹅城再收一轮税——房产税落地如何重塑中美房产配置策略（下）","categories":"社会观察","tags":["投资","劳动与经济","制度","阶层与身份"],"description":"一、基准线：中美持有成本的落差有多大？ 在讨论”冲击”之前，必须先确认一个事实——当前中美房产持有成本的差距，不是百分之几的差距，而是数量级的差距。 以一套价值50万美元（约360万人民币）的房产为例： 持有成本项美国（…","date":"2026-09-19T12:00:00.000Z","series":"从iPhone到鹅城","seriesOrder":2},"headers":[],"relativePath":"posts/2026-09-19-from-iphone-to-goose-town-part-2.md","filePath":"posts/2026-09-19-from-iphone-to-goose-town-part-2.md","lastUpdated":1789992797000}'),s={name:"posts/2026-09-19-from-iphone-to-goose-town-part-2.md"};function e(l,r,i,p,g,h){return t(),a("div",null,[...r[0]||(r[0]=[n('<h1 id="鹅城再收一轮税——房产税落地如何重塑中美房产配置策略-下" tabindex="-1">鹅城再收一轮税——房产税落地如何重塑中美房产配置策略（下） <a class="header-anchor" href="#鹅城再收一轮税——房产税落地如何重塑中美房产配置策略-下" aria-label="Permalink to &quot;鹅城再收一轮税——房产税落地如何重塑中美房产配置策略（下）&quot;">​</a></h1><h3 id="一、基准线-中美持有成本的落差有多大" tabindex="-1">一、基准线：中美持有成本的落差有多大？ <a class="header-anchor" href="#一、基准线-中美持有成本的落差有多大" aria-label="Permalink to &quot;一、基准线：中美持有成本的落差有多大？&quot;">​</a></h3><p>在讨论”冲击”之前，必须先确认一个事实——当前中美房产持有成本的差距，不是百分之几的差距，而是<strong>数量级的差距</strong>。</p><p>以一套价值50万美元（约360万人民币）的房产为例：</p><p>持有成本项美国（年）中国（年）倍数差房产税5,000-15,000美元0元（非试点城市）∞房屋保险800-2,500美元0元（非强制）∞维护维修3,000-7,500美元几乎为零（物业覆盖）—物业费/HOA2,400-9,600美元2,400-7,200元约7-9倍年持有总成本（全区间）约1.1万-3.5万美元约2,400-7,200元—占房价比例（全区间）2.2%-7%0.07%-0.2%—<em>注：美国数据基于2025-2026年全美平均水平估算，实际因州、城市差异巨大（如新泽西有效房产税率超2%，德州部分县超2.5%，而夏威夷仅约0.3%）。中国数据基于非试点城市现状。按1美元=7.0元折算；美国全区间7.7万-24.5万元人民币 vs 中国0.24万-0.72万元，为10-100倍。</em></p><p>这意味着：在中国持有一套500万的房子，每年只需付出2,400-7,200元的持有成本；而在美国持有一套同等价值的房子，每年要付出约7.7万-24.5万元。<strong>中国的持有成本不足美国的1/10。</strong></p><p>这正是”中国租房”策略的核心支撑——你花5000元/月租一套价值500万的房子，房东每年承担2,400-7,200元的持有成本，而你几乎零持有成本。从纯经济角度看，你是在”白嫖”房东的资产。</p><h3 id="二、房产税如果落地-持有成本会被重塑到什么程度" tabindex="-1">二、房产税如果落地：持有成本会被重塑到什么程度？ <a class="header-anchor" href="#二、房产税如果落地-持有成本会被重塑到什么程度" aria-label="Permalink to &quot;二、房产税如果落地：持有成本会被重塑到什么程度？&quot;">​</a></h3><h3 id="_2-1-最可能的制度设计" tabindex="-1">2.1 最可能的制度设计 <a class="header-anchor" href="#_2-1-最可能的制度设计" aria-label="Permalink to &quot;2.1 最可能的制度设计&quot;">​</a></h3><p>基于上海、重庆试点经验和学界讨论，全国版房产税最可能的设计框架是：</p><ul><li><strong>免征面积</strong>：人均40-60平方米（首套或人均面积内免税）</li><li><strong>税率</strong>：0.4%-1.2%（阶梯式，按房价分档）</li><li><strong>计税依据</strong>：房产评估价值的70%-100%</li><li><strong>征收对象</strong>：家庭第二套及以上住房，或超出免征面积的部分</li></ul><p>上海试点中，95%以上家庭符合免税条件；重庆实际需缴税家庭不足3%。</p><h3 id="_2-2-分情景测算" tabindex="-1">2.2 分情景测算 <a class="header-anchor" href="#_2-2-分情景测算" aria-label="Permalink to &quot;2.2 分情景测算&quot;">​</a></h3><p>以一线城市一套价值800万元、面积100平方米的住房为例，三口之家（免征面积180平方米）：</p><p><strong>情景一：首套房，面积未超免征线</strong></p><p>项目当前房产税落地后年房产税0元0元（未超免征面积）年物业费~6,000元~6,000元年持有总成本~6,000元~6,000元占房价比例0.075%0.075%<strong>结论：对首套刚需家庭，房产税几乎零冲击。策略不变。</strong></p><p><strong>情景二：二套房，超出免征面积</strong></p><p>假设家庭已有首套120平方米，新购二套100平方米、价值800万：</p><p>项目当前房产税落地后年房产税0元800万×70%×0.6%=33,600元年物业费~6,000元~6,000元年持有总成本~6,000元~39,600元占房价比例0.075%0.5%<strong>结论：多套房持有者成本上升约6倍，但占房价比例仍远低于美国的2.5%-4%。</strong></p><p><strong>情景三：高端住宅/多套持有（极端情况）</strong></p><p>假设持有3套房产，总价值3000万元，超出免征面积部分按1.0%征收：</p><p>项目当前房产税落地后年房产税0元约20-30万元年物业费~18,000元~18,000元年持有总成本~18,000元~22-32万元占房价比例0.06%0.7%-1.1%<strong>结论：即使对极端多套房持有者，中国房产税落地后的持有成本占比（0.7%-1.1%），仍然只有美国平均水平（2.5%-4%）的1/3到1/4。</strong></p><h3 id="三、关键发现-中美持有成本的差距不会因房产税而逆转" tabindex="-1">三、关键发现：中美持有成本的差距不会因房产税而逆转 <a class="header-anchor" href="#三、关键发现-中美持有成本的差距不会因房产税而逆转" aria-label="Permalink to &quot;三、关键发现：中美持有成本的差距不会因房产税而逆转&quot;">​</a></h3><p>这是整篇分析最重要的结论——</p><p><strong>即使房产税全面落地，中国房产的年持有成本占房价比例（0.5%-1.1%），仍然只有美国（2.5%-4%）的1/4到1/3。</strong></p><p>原因很简单：</p><ul><li><strong>免征面积大幅稀释了实际税负。</strong> 上海试点中，实际需缴税的家庭占比不超过5%。全国版大概率延续”保障基本居住”的原则，人均40-60平方米免征意味着大部分家庭的自住房不会被触及。</li><li><strong>税率上限远低于美国。</strong> 中国试点税率0.4%-0.6%，即使未来提高到1.2%，仍低于美国中位数（全美有效税率普遍在1%-3%之间，新泽西高达2.11%-2.3%）。</li><li><strong>美国还有保险、维护等隐性成本。</strong> 美国房产年维护费约5,000-11,000美元，保险约1,500-3,000美元，这些在中国几乎不存在。</li></ul><p><strong>换句话说，房产税落地后，”中国持有成本极低”这个基本面不会改变。</strong></p><h3 id="四、房产税的资本化效应——税落地后房价跌多少" tabindex="-1">四、房产税的资本化效应——税落地后房价跌多少？ <a class="header-anchor" href="#四、房产税的资本化效应——税落地后房价跌多少" aria-label="Permalink to &quot;四、房产税的资本化效应——税落地后房价跌多少？&quot;">​</a></h3><p>读者最关心的其实不是”每年多交多少税”，而是“<strong>税落地后，我手里的房子会跌多少</strong>”。</p><p>金融学对此有一个经典结论：<strong>未来税负会被”资本化”进当期房价。</strong> 逻辑很简单——如果持有一套房子每年要多交1%的税，而租金回报率只有1.5%，那这套房子的”净收益率”就从1.5%压缩到0.5%。为了恢复合理的收益率，房价必须下跌，直到净收益率回到市场均衡水平。</p><h3 id="粗算-理论折价幅度" tabindex="-1">粗算：理论折价幅度 <a class="header-anchor" href="#粗算-理论折价幅度" aria-label="Permalink to &quot;粗算：理论折价幅度&quot;">​</a></h3><p>按简化模型估算：假设房产税税率1%，市场资本化率（cap rate）5%，则理论折价幅度约为：</p><blockquote><p><strong>折价 ≈ 税率 / 资本化率 = 1% / 5% = 20%</strong></p></blockquote><p>这意味着，如果房产税按1%全面落地，理论上房价需要下跌约20%才能消化新增税负。当然，这是极端简化——实际折价取决于免征面积设计、市场供需关系、利率环境等多重因素。</p><h3 id="首套免征结构大幅缓冲冲击" tabindex="-1">首套免征结构大幅缓冲冲击 <a class="header-anchor" href="#首套免征结构大幅缓冲冲击" aria-label="Permalink to &quot;首套免征结构大幅缓冲冲击&quot;">​</a></h3><p>但中国最可能的制度设计是”首套免征”或”人均面积内免征”。在这种结构下：</p><ul><li><strong>首套刚需家庭</strong>：税负为零，房价不受资本化压力，<strong>理论上零冲击</strong>。</li><li><strong>二套及以上</strong>：税负全额承担，理论折价15%-20%，但实际跌幅取决于市场流动性和抛售压力。</li><li><strong>三四线城市多套房</strong>：叠加人口流出和空置率高企，可能出现”折价也卖不掉”的流动性枯竭。</li></ul><h3 id="一个反直觉的推论" tabindex="-1">一个反直觉的推论 <a class="header-anchor" href="#一个反直觉的推论" aria-label="Permalink to &quot;一个反直觉的推论&quot;">​</a></h3><p>房产税资本化效应意味着：<strong>税还没落地，”税要落地”的预期本身就会压低房价。</strong> 2021年以来中国房价的持续下跌，除了人口因素和信贷收紧外，”房产税迟早要来”的预期可能已经提前部分计入了房价。</p><p>这也是为什么房产税迟迟不落地——<strong>最受伤的群体（多套房持有者）恰恰是拥有最强政策阻滞能力的群体。</strong> 税之所以落不了地，和税落地后谁最痛，是同一个问题的两面。</p><h3 id="五、-已经收了70年-凭什么再收一遍-——房产税的合法性之争" tabindex="-1">五、”已经收了70年，凭什么再收一遍？”——房产税的合法性之争 <a class="header-anchor" href="#五、-已经收了70年-凭什么再收一遍-——房产税的合法性之争" aria-label="Permalink to &quot;五、”已经收了70年，凭什么再收一遍？”——房产税的合法性之争&quot;">​</a></h3><h3 id="_5-1-官方的法理逻辑-性质不同-不构成重复征税" tabindex="-1">5.1 官方的法理逻辑：”性质不同，不构成重复征税” <a class="header-anchor" href="#_5-1-官方的法理逻辑-性质不同-不构成重复征税" aria-label="Permalink to &quot;5.1 官方的法理逻辑：”性质不同，不构成重复征税”&quot;">​</a></h3><p>官方的立场非常明确：<strong>土地出让金和房产税是两个完全不同的东西，各行其道，不矛盾、不重复。</strong></p><p>具体论据如下：</p><p><strong>身份不同：</strong> 政府收土地出让金时，身份是“<strong>地主</strong>”——作为土地所有者，向使用权人收取地租，这是市场交易行为，体现等价交换。政府收房产税时，身份是“<strong>管理者</strong>”——作为社会管理者，凭借政治权力依法征税，这是强制性的二次分配。</p><p><strong>环节不同：</strong> 土地出让金发生在<strong>取得环节</strong>（买房时一次性付清），房产税发生在<strong>保有环节</strong>（每年持续缴纳）。一个是”进门费”，一个是”年费”。</p><p><strong>性质不同：</strong> 土地出让金本质是<strong>地租</strong>，属于国民收入初次分配；房产税本质是<strong>财产税</strong>，属于国民收入二次分配。一个是”租”，一个是”税”，租税并行，法理上各行其道。</p><p><strong>产权基础：</strong> 《民法典》第359条明确了住宅建设用地使用权期限届满<strong>自动续期</strong>，这在事实上赋予了土地使用权极强的”准私有物权”属性。用益物权具有财产性质，可以成为征税对象。</p><p><strong>国际先例：</strong> 在英联邦国家的”王室土地（Crown Land）”制度下，土地名义上归国家或王室所有，个人获取的是有期限的租借权（Leasehold），但政府依然对持有长期租借权的居民征收财产税。</p><h3 id="_5-2-公众的直觉逻辑-实质就是重复征收" tabindex="-1">5.2 公众的直觉逻辑：”实质就是重复征收” <a class="header-anchor" href="#_5-2-公众的直觉逻辑-实质就是重复征收" aria-label="Permalink to &quot;5.2 公众的直觉逻辑：”实质就是重复征收”&quot;">​</a></h3><p>官方的法理逻辑在理论上自洽，但公众的质疑同样有坚实的依据：</p><p><strong>“一鱼两吃”的实质：</strong> 你花500万买房，其中约300万是隐含在房价中的土地出让金——你已经一次性预缴了70年的地租。如果2026年再按500万市值征收1%的房产税，每年交5万，70年就是350万。<strong>政府既收了300万地租，又收了350万房产税，合计650万——远超房子本身的价值。</strong> 这难道不是对同一标的物的双重征收？</p><p><strong>产权的不对称：</strong> 西方国家征收房产税的前提是<strong>土地永久私有</strong>——你拥有完整的产权，政府每年收税换取公共服务，逻辑自洽。而中国购房者仅拥有<strong>70年使用权</strong>，土地所有权归国家，70年后土地要归还。对一项有期限的使用权，长期征收基于永久所有权逻辑的财产税，法理基础显然不够坚实。</p><p><strong>续期的不确定性：</strong> 《民法典》只规定了70年产权到期<strong>自动续期</strong>，但续期是否收费、收费标准、办理流程，至今没有明确答案。在民生底线没有厘清的情况下急着推进房产税，属于本末倒置。</p><p><strong>税负的不对等：</strong> 2024年重庆房产税收入仅46亿元（含经营性不动产，重庆市财政局数据），而同期土地出让收入1528亿元——房产税根本替代不了土地出让金。如果房产税无法替代土地出让金，那它就是在原有税费基础上的<strong>净增加</strong>，而不是”转换”。</p><h3 id="_5-3-为什么中国-敢-收-——权力的本质" tabindex="-1">5.3 为什么中国”敢”收？——权力的本质 <a class="header-anchor" href="#_5-3-为什么中国-敢-收-——权力的本质" aria-label="Permalink to &quot;5.3 为什么中国”敢”收？——权力的本质&quot;">​</a></h3><p>“中国还敢收吗”——这个问题的答案不在法理层面，而在<strong>权力结构</strong>层面。</p><p><strong>第一，立法权的垄断。</strong> 在中国，税种的设立、税率的确定，最终由全国人大及其常委会决定。而全国人大的立法方向，与执政党的政策方针高度一致。当决策层认为房产税是”地方财政转型的必然选择”时，法理障碍可以通过立法程序来”解决”——<strong>不是先有法理再有法律，而是先有政策需要，再通过立法赋予合法性。</strong></p><p><strong>第二，产权制度的”弹性”。</strong> 中国的土地制度本身就是一个”弹性框架”——土地归国家所有，但使用权可以转让、抵押、继承，70年到期自动续期。这种”名义公有、实质私用”的模糊地带，为政策操作留下了巨大空间。<strong>官方可以说”使用权就是财产权，可以征税”；公众可以说”使用权不是所有权，不该征税”——双方都有依据，但最终谁说了算，取决于立法者。</strong></p><p><strong>第三，”受益原则”的话语建构。</strong> 官方正在构建一套叙事：房产税不是”重复收费”，而是你为享受公共服务（治安、教育、医疗、基础设施）支付的”对价”。房子之所以升值，很大程度上来源于周边公共配套的溢价，因此作为受益者承担税收义务具有正当性。这套叙事的巧妙之处在于——<strong>它把”征税”重新定义为”付费购买服务”，从而绕开了”重复征收”的道德困境。</strong></p><h3 id="_5-4-现实的推进节奏——-敢-但不急" tabindex="-1">5.4 现实的推进节奏——”敢”但不急 <a class="header-anchor" href="#_5-4-现实的推进节奏——-敢-但不急" aria-label="Permalink to &quot;5.4 现实的推进节奏——”敢”但不急&quot;">​</a></h3><p>虽然法理上”可以收”，但现实中推进极其谨慎：</p><ul><li>截至2026年，全国仅<strong>上海和重庆</strong>两座城市维持个人住房房产税试点，且实际需缴税的家庭占比不超过5%。</li><li>财政部明确表态：2026年内<strong>不具备扩大试点城市的条件</strong>。</li><li>2023年公布的十四届全国人大常委会立法规划<strong>未提及房地产税法</strong>，本届任期内立法暂缓。</li><li>2021年10月全国人大常委会授权国务院开展试点的五年期限将于<strong>2026年10月期满</strong>，但新一批试点尚未落地。</li><li>上海试点已延长至2031年，重庆持续优化但<strong>未扩大征收范围</strong>。</li></ul><p><strong>为什么”敢”但”不急”？</strong> 因为决策层非常清楚：</p><ul><li><strong>房地产市场仍在企稳阶段</strong>，贸然扩围可能引发恐慌性抛售，冲击金融系统。</li><li><strong>社会接受度极低</strong>，”已经交了70年地租还要再交税”的民意反弹是真实的政治风险。</li><li><strong>替代税源尚未就位</strong>——消费税后移、地方附加税改革等替代方案还在推进中。</li><li><strong>技术准备仍需时间</strong>——全国不动产估价体系、住房信息联网、税源数据库等基础设施尚未完全就绪。</li><li>另一层政治经济学原因见第四章——<strong>最受伤的群体恰恰是拥有最强政策阻滞能力的群体</strong>，税之所以落不了地，和税落地后谁最痛，是同一个问题的两面。</li></ul><h3 id="_5-5-未来的可能路径——-租税合一-还是-租税并行" tabindex="-1">5.5 未来的可能路径——”租税合一”还是”租税并行”？ <a class="header-anchor" href="#_5-5-未来的可能路径——-租税合一-还是-租税并行" aria-label="Permalink to &quot;5.5 未来的可能路径——”租税合一”还是”租税并行”？&quot;">​</a></h3><p>学界和政策界对此存在三种主要方案：</p><p><strong>方案一：租税并行（官方倾向）</strong></p><p>保持土地出让金不变，另行开征房产税。通过制度设计（如首套房免征、人均面积扣除、低税率）来缓解”重复征收”的感知。有学者提出”已缴出让金抵扣机制”——在计算房产税时，扣除已缴纳的土地出让金对应的价值，避免对同一标的物的双重征收。</p><p><strong>方案二：租税合一（激进改革派）</strong></p><p>废除土地出让金制度，改为每年征收房产税，实现从”一次性买断”到”逐年分期”的转换。这相当于把中国的模式彻底切换为美国模式。但这意味着地方财政将失去一笔巨额的一次性收入，短期内财政缺口无法弥补。</p><p><strong>方案三：渐进过渡（最可能）</strong></p><p>先对新出让的土地实行”年租制”（不再一次性收取70年地租，改为逐年收取），同时对存量房产设置较长的过渡期（如10-20年），逐步开征房产税。最终实现”新老划断”——新房新办法，老房老办法。</p><h3 id="六、房产税与公共服务质量的-交易逻辑" tabindex="-1">六、房产税与公共服务质量的”交易逻辑” <a class="header-anchor" href="#六、房产税与公共服务质量的-交易逻辑" aria-label="Permalink to &quot;六、房产税与公共服务质量的”交易逻辑”&quot;">​</a></h3><p>以上只是”算账”和”辩论”，但房产税的真正深意不在账面上，也不在法理上，而在于它可能从根本上改变地方政府的行为模式。</p><h3 id="_6-1-美国模式-你看得见钱花在哪了" tabindex="-1">6.1 美国模式：你看得见钱花在哪了 <a class="header-anchor" href="#_6-1-美国模式-你看得见钱花在哪了" aria-label="Permalink to &quot;6.1 美国模式：你看得见钱花在哪了&quot;">​</a></h3><p>美国房产税高（有效税率1%-3%），但纳税人能<strong>看见</strong>钱花在哪了——公立学校、消防站、社区公园、道路维护、图书馆，全是从房产税里出的。2026年北卡罗来纳州韦克县的数据显示，房产税承担了约75%的年度预算。</p><p>这形成了一种“<strong>税收-服务对价关系</strong>”：你每年交房产税，换取可量化的公共服务。学校好不好、路修得好不好、治安怎么样——这些直接决定了你的房子值多少钱，也决定了你愿不愿意继续住在这里、继续交这个税。</p><p>2026年美国多州出现的”房产税大战”恰好印证了这种对价关系的张力：佛罗里达州提议提高自住房免税额，市长们警告这可能令预算减少约三分之一，导致道路恶化、图书馆和公园关闭、公共安全响应时间延长。选民在”少交税”和”保住服务”之间反复拉扯——<strong>这恰恰说明美国的房产税是一种”明码标价的交易”，而不是一种单向的征收。</strong></p><h3 id="_6-2-中国模式-你看不见钱花在哪了" tabindex="-1">6.2 中国模式：你看不见钱花在哪了 <a class="header-anchor" href="#_6-2-中国模式-你看不见钱花在哪了" aria-label="Permalink to &quot;6.2 中国模式：你看不见钱花在哪了&quot;">​</a></h3><p>中国的土地出让金呢？你花500万买房，其中约300万是隐含在房价中的土地出让金——你已经一次性预缴了70年的”地租”。但这笔钱花在哪了？道路？学校？地铁？你说不清楚，因为它被混入了地方财政的”大池子”里，和公务员薪资、行政开支、产业补贴搅在一起。</p><p><strong>这就是两种模式的本质区别：美国的房产税是”你交钱，我服务”的显性交易；中国的土地出让金是”你交钱，我花了，花在哪你别问”的隐性征收。</strong></p><h3 id="_6-3-房产税可能倒逼治理转型" tabindex="-1">6.3 房产税可能倒逼治理转型 <a class="header-anchor" href="#_6-3-房产税可能倒逼治理转型" aria-label="Permalink to &quot;6.3 房产税可能倒逼治理转型&quot;">​</a></h3><p>如果中国开征房产税，一个深远的影响可能浮现——<strong>纳税人开始要求”对价”</strong>。</p><p>当你每年被要求为同一套房子再交一笔税时，你自然会问：<strong>“这笔钱花在哪了？我家门口的路修了吗？我孩子的学校变好了吗？”</strong> 这种追问一旦形成规模，就会倒逼地方政府从”卖地赚钱”转向”靠服务留人”。</p><p>逻辑链条是这样的：</p><blockquote><p>房产税落地 → 纳税人要求公共服务对价 → 地方政府必须提升服务质量以维持税基 → 从”地主”变成”管家” → 从依赖土地财政转向依赖服务竞争力</p></blockquote><p><strong>房产税不只是”多收一笔钱”，它可能从根本上改变地方政府的行为激励——从依赖土地财政的”地主”，变成依赖服务质量的”管家”。</strong> 这在中国治理史上，可能是一次静悄悄的范式转换。</p><p>当然，这个转换的前提是：房产税的用途必须透明，纳税人必须有渠道表达诉求。否则，房产税就只是”又一笔不知道花在哪的钱”，和土地出让金没有本质区别。</p><h3 id="七、房产-投资属性-的消退与-消费属性-的回归" tabindex="-1">七、房产”投资属性”的消退与”消费属性”的回归 <a class="header-anchor" href="#七、房产-投资属性-的消退与-消费属性-的回归" aria-label="Permalink to &quot;七、房产”投资属性”的消退与”消费属性”的回归&quot;">​</a></h3><h3 id="_7-1-过去20年-房子是-投资品" tabindex="-1">7.1 过去20年：房子是”投资品” <a class="header-anchor" href="#_7-1-过去20年-房子是-投资品" aria-label="Permalink to &quot;7.1 过去20年：房子是”投资品”&quot;">​</a></h3><p>过去20年，中国房子之所以被疯抢，核心不是”住”，而是”涨”。房子是投资品，是财富储存工具，是”抗通胀神器”。丈母娘要的不是”女婿有地方住”，而是”女婿的资产在增值”。</p><h3 id="_7-2-房产税落地后-房子正在回归-消费品" tabindex="-1">7.2 房产税落地后：房子正在回归”消费品” <a class="header-anchor" href="#_7-2-房产税落地后-房子正在回归-消费品" aria-label="Permalink to &quot;7.2 房产税落地后：房子正在回归”消费品”&quot;">​</a></h3><p>当持有成本从接近零变成每年0.5%-1%，而租金回报率只有1.5%时，房子的”净收益”被压缩到几乎为零，甚至为负。这意味着什么？<strong>房子正在从”投资品”回归”消费品”。</strong> 你买房不再是为了”赚钱”，而是为了”住”——就像你买一辆车，不会指望它升值。</p><p>这个转变的深远影响是：</p><ul><li><strong>丈母娘经济的瓦解</strong>——如果房子不再升值，”有房才有家”的社会共识会不会松动？2025年的数据已经显示，73%的00后3年内不计划买房，30岁以下购房占比从2018年的46.9%腰斩至25.3%。</li><li><strong>租房文化的兴起</strong>——当买房不再是最优财务决策时，年轻人会不会更愿意租房？全国租房人口规模已超2.6亿，部分年轻人选择长期租房后直接购买改善型住房。</li><li><strong>财富储存方式的转移</strong>——从房子转向股票、基金、REITs、甚至加密资产。2025年居民部门债务增速仅0.5%，个人住房贷款增速连续11个季度负增长，”收入不稳定”成为影响购房决策的首要因素。</li></ul><h3 id="_7-3-上海大学聂永有教授的判断" tabindex="-1">7.3 上海大学聂永有教授的判断 <a class="header-anchor" href="#_7-3-上海大学聂永有教授的判断" aria-label="Permalink to &quot;7.3 上海大学聂永有教授的判断&quot;">​</a></h3><p>2026年2月”沪七条”新政出台后，上海大学经济学院教授聂永有指出：制约上海房地产市场长期走势的<strong>人口变化、供求关系逆转以及住房功能回归消费本质</strong>等因素并未根本改变。</p><p>“住房功能回归消费本质”——这七个字，可能是理解未来十年中国房地产最关键的判断。</p><h3 id="八、人口结构-房产税之外的-第二把刀" tabindex="-1">八、人口结构：房产税之外的”第二把刀” <a class="header-anchor" href="#八、人口结构-房产税之外的-第二把刀" aria-label="Permalink to &quot;八、人口结构：房产税之外的”第二把刀”&quot;">​</a></h3><p>房产税是政策冲击，但还有一个更深层的结构性力量在同时作用于房价——<strong>人口</strong>。</p><h3 id="_8-1-中国的人口悬崖" tabindex="-1">8.1 中国的人口悬崖 <a class="header-anchor" href="#_8-1-中国的人口悬崖" aria-label="Permalink to &quot;8.1 中国的人口悬崖&quot;">​</a></h3><p>2025年末全国总人口140,489万人，较上年减少339万人，自然增长率为-2.41‰，连续第四年负增长。全年出生人口792万人，出生率5.63‰，创1949年以来新低。</p><p>更关键的是<strong>购房主力人群的绝对数量正在快速萎缩</strong>：</p><ul><li>25-39岁刚需主力人群2020年约3.2亿人，2024年降至约2.85亿人，<strong>年均减少约870万人</strong>。</li><li>20-45岁购房主力人口年均减少600万。</li><li>20-64岁适龄购房人群到2050年将减少约2亿人，对应减少约7610万套住房需求。</li></ul><p>全国31个省份中仅7个常住人口增加，24个省份减少，新增人口89%被前20个大城市吸纳。</p><h3 id="_8-2-日本的教训-人口下降对房价的打击是持续性的、不可逆的" tabindex="-1">8.2 日本的教训：人口下降对房价的打击是持续性的、不可逆的 <a class="header-anchor" href="#_8-2-日本的教训-人口下降对房价的打击是持续性的、不可逆的" aria-label="Permalink to &quot;8.2 日本的教训：人口下降对房价的打击是持续性的、不可逆的&quot;">​</a></h3><p>日本的经验表明，人口下降对房价的影响不是”短期波动”，而是<strong>结构性坍塌</strong>。</p><p>截至2023年10月，日本全国空置房屋（空き家）数量攀升至900万套，空置率13.8%，创历史新高——<strong>平均每7套住宅就有1套空置</strong>。其中约385万套处于既不租也不卖的彻底遗弃状态。</p><p>野村研究所预测，若不进行大规模拆除，到2038年空置房屋将增至2303万套，空置率达31%——<strong>届时日本每三套房子中就有一套是空屋</strong>。</p><p>日本2025年全年新生儿仅67.1万人，总和生育率降至1.14，总人口连续17年下降，2026年初公布的数据显示已时隔42年首次跌破1.2亿大关。</p><p>更触目惊心的是”继承陷阱”：日本大量空置房因税费过高无人继承——遗产税最高达55%，加上固定资产税及物业费年度支出可达房价3%，导致子女宁弃继承也不愿负担。</p><h3 id="_8-3-房产税-人口下降-两把刀同时砍" tabindex="-1">8.3 房产税+人口下降：两把刀同时砍 <a class="header-anchor" href="#_8-3-房产税-人口下降-两把刀同时砍" aria-label="Permalink to &quot;8.3 房产税+人口下降：两把刀同时砍&quot;">​</a></h3><p>房产税是政策强制增加持有成本，人口下降是结构性减少需求。两者叠加，对三四线城市房价的杀伤力远超任何单一因素。</p><p>2026年的数据已经显示：三四线城市及县城空置率普遍超22%，部分人口流失城市达30%-40%；全国城镇住宅空置率约16.7%-21.3%，对应空置住宅约6500万套。</p><p>高盛预测城镇年度新房需求已降至500-800万套，较2017年峰值下降四到六成。</p><p><strong>日本的经验表明：核心城市（东京）尚能维持，但大量中小城市房价跌至”白送都没人要”。中国的人口趋势正在沿着相似的轨迹运行——购房主力人群年均减少数百万、三四线城市人口持续流出——而房产税一旦落地，将成为叠加在人口下降之上的第二重压力。</strong></p><h3 id="九、全球房产配置地图-不只是中美两国" tabindex="-1">九、全球房产配置地图：不只是中美两国 <a class="header-anchor" href="#九、全球房产配置地图-不只是中美两国" aria-label="Permalink to &quot;九、全球房产配置地图：不只是中美两国&quot;">​</a></h3><p>既然讨论”在哪里买房最划算”，只讲中美太窄了。以下是一张全球房产配置的横向对比地图：</p><p>市场毛租金回报率有效房产税率产权性质人口趋势适合人群美国中西部5%-7%1%-2%永久私有缓慢增长长线投资者美国阳光带（佛州、德州）7%-9%0.8%-1.7%永久私有人口流入高回报追求者日本东京（核心区）1.5%-2.0%1.4%-2.1%永久私有负增长稳健配置日本东京（全市平均）2.5%-3.0%1.4%-2.1%永久私有负增长收益型投资者日本大阪3.5%-4.5%1.4%-2.1%永久私有负增长收益型投资者泰国曼谷5.5%-7%极低外国人限公寓正增长低成本套利阿联酋迪拜6%-8%无房产税自贸区永久人口流入高回报+免税英国（曼城等）6%-8%1%-1.2%（市政税）永久私有缓慢增长收益型投资者中国一线1.3%-2.0%接近零→可能上升70年使用权负增长刚需自住中国三四线2%-3%接近零70年使用权加速流出回避几个关键发现：</p><ul><li><strong>芝加哥的毛租金回报率约6%-8%</strong>（2025-2026年数据，新兴社区如Bronzeville、Avondale可达7%-8%，核心商务区较低），全美住宅平均毛租金回报率约6.5%，休斯顿、费城、芝加哥等内陆城市可达8%-9%——美国内陆城市的租售比健康程度远超中国想象。洛杉矶、旧金山3%-4%的回报率在美国内部属于偏低水平，但仍显著高于北京上海的1.3%-1.4%；真正与北京上海处于同一梯队的是东京核心区（1.5%-2%）——但东京是永久产权，北京上海是70年使用权，产权性质的差异使得同等回报率下的投资价值截然不同。</li><li><strong>迪拜没有房产税</strong>，租金回报率6%-8%，且2025年住宅价格上涨12.8%——对追求高收益的投资者极具吸引力。</li><li><strong>泰国曼谷5.5%-7%的回报率</strong>，叠加极低的生活成本和外国人可购公寓的政策，是”低成本套利”的典型标的。</li></ul><p><strong>一句话总结：全球范围内，你的钱应该放在永久产权+高租金回报+人口流入的市场；回避70年使用权+低租金回报+人口流出的市场。</strong></p><h3 id="十、代际财富转移的-继承陷阱" tabindex="-1">十、代际财富转移的”继承陷阱” <a class="header-anchor" href="#十、代际财富转移的-继承陷阱" aria-label="Permalink to &quot;十、代际财富转移的”继承陷阱”&quot;">​</a></h3><p>房产税对”继承房产”的冲击是一个被严重低估的话题。</p><h3 id="_10-1-中国正在逼近-继承高峰" tabindex="-1">10.1 中国正在逼近”继承高峰” <a class="header-anchor" href="#_10-1-中国正在逼近-继承高峰" aria-label="Permalink to &quot;10.1 中国正在逼近”继承高峰”&quot;">​</a></h3><p>中国大量家庭的财富以房产形式存在，且面临代际转移。60后、70后持有多套房产，2036年前后将进入继承密集期。</p><p>如果房产税落地，子女继承一套价值800万的老房子，每年要交3-5万房产税，但这套房可能根本租不出去（三四线城市）——<strong>“继承来的房子”从”资产”变成”负债”</strong>。你不敢卖（怕跌），不敢住（不在那个城市），但每年要交税。</p><h3 id="_10-2-日本的-空き家-就是前车之鉴" tabindex="-1">10.2 日本的”空き家”就是前车之鉴 <a class="header-anchor" href="#_10-2-日本的-空き家-就是前车之鉴" aria-label="Permalink to &quot;10.2 日本的”空き家”就是前车之鉴&quot;">​</a></h3><p>日本大量空置房因税费过高无人继承。子女面对的不是一笔财富，而是一个“<strong>负资产陷阱</strong>”——继承意味着承担每年的固定资产税、物业费、修缮费，而房子本身既租不出去也卖不掉。</p><p>截至2023年10月，日本全国空置房已达900万套，其中385万套处于彻底遗弃状态。</p><h3 id="_10-3-中国会重蹈覆辙吗" tabindex="-1">10.3 中国会重蹈覆辙吗？ <a class="header-anchor" href="#_10-3-中国会重蹈覆辙吗" aria-label="Permalink to &quot;10.3 中国会重蹈覆辙吗？&quot;">​</a></h3><p>2026年的数据已经显示了一些早期信号：</p><ul><li>全国城镇住宅空置率约16.7%-21.3%，对应空置住宅约6500万套（详见第八章人口结构分析）。</li><li>三四线城市及县城空置率普遍超22%，部分人口流失城市达30%-40%。</li><li>2025年北京、上海学区房价格同比下跌15%-20%，非核心学区”老破小”价格跌幅接近30%。</li></ul><p><strong>房产税+人口下降，正在制造一个”继承陷阱”——尤其是对人口流出城市的老旧房产。</strong> 你继承的不是财富，而是每年必须缴纳的税负和不断贬值的资产。</p><h3 id="十一、美国策略的风险清单——-美国买房-不是无条件成立的" tabindex="-1">十一、美国策略的风险清单——”美国买房”不是无条件成立的 <a class="header-anchor" href="#十一、美国策略的风险清单——-美国买房-不是无条件成立的" aria-label="Permalink to &quot;十一、美国策略的风险清单——”美国买房”不是无条件成立的&quot;">​</a></h3><p>我们推荐”美国买房”策略时，必须同时披露一个被中介刻意隐瞒的事实：<strong>这套策略有严格的适用前提，对普通中产而言，执行门槛远高于表面所见。</strong></p><h3 id="_11-1-遗产税-非美国税务居民的-隐形杀手" tabindex="-1">11.1 遗产税：非美国税务居民的”隐形杀手” <a class="header-anchor" href="#_11-1-遗产税-非美国税务居民的-隐形杀手" aria-label="Permalink to &quot;11.1 遗产税：非美国税务居民的”隐形杀手”&quot;">​</a></h3><p><strong>非美国税务居民（Non-Resident Alien）继承美国房产时，联邦遗产税免税额仅6万美元，超出部分税率最高40%。</strong></p><p>假设一对中国夫妇以个人名义持有一套价值50万美元的美国房产，其中一人去世：</p><p>项目金额房产市值500,000美元免税额60,000美元应税金额440,000美元联邦遗产税（适用累进税率，最高40%）约15万-17万美元<strong>一套50万美元的房子，传承一次就要交掉约30%-35%的遗产税。</strong> 相比之下，美国公民和税务居民的遗产税免税额为1500万美元（2026年，OBBBA立法后），绝大多数美国家庭根本不需要缴纳遗产税。</p><p>更棘手的是：中美之间<strong>没有遗产税协定</strong>，无法享受免税额提升或税收抵免。同时由于中国尚未开征遗产税，也不存在跨境抵免对象——真正的问题在于资产汇回环节的成本与合规约束。</p><p>常见的规避方式包括：通过外国公司或信托持有房产（使其在税务上被视为非美国资产，但需注意房产本身始终属于美国不动产，被”视为非美国资产”的是公司或信托的股权；误用架构可能触发30%分支机构利润税等更严重后果）、购买人寿保险覆盖遗产税、或提前做赠与规划。但这些都需要专业税务架构设计，成本不菲。</p><h3 id="_11-2-firpta预扣税-卖房时被-冻结-的现金流" tabindex="-1">11.2 FIRPTA预扣税：卖房时被”冻结”的现金流 <a class="header-anchor" href="#_11-2-firpta预扣税-卖房时被-冻结-的现金流" aria-label="Permalink to &quot;11.2 FIRPTA预扣税：卖房时被”冻结”的现金流&quot;">​</a></h3><p>外国人出售美国房产时，适用《外国人投资房地产税法》（FIRPTA），<strong>买方须按售价的15%预扣税款</strong>。这不是最终税负——申报后可按实际资本利得多退少补——但现金流压力巨大。</p><p>举例：一套50万美元的房子以70万美元出售，账面利润20万美元。但买方须预扣10.5万美元（70万×15%），你实际到手的现金大幅缩水，直到次年申报所得税后才能申请退回多扣部分。</p><p>此外，美国公民和税务居民出售主要自住房时可享受单身25万美元、夫妻50万美元的资本利得免税额（Section 121），<strong>外国人通常不能享受这项优惠</strong>。</p><h3 id="_11-3-换汇约束-500万不是想汇就能汇" tabindex="-1">11.3 换汇约束：500万不是想汇就能汇 <a class="header-anchor" href="#_11-3-换汇约束-500万不是想汇就能汇" aria-label="Permalink to &quot;11.3 换汇约束：500万不是想汇就能汇&quot;">​</a></h3><p>中国居民每人每年5万美元的便利化购汇额度，意味着配置一套50万美元（约360万人民币）的美国房产，<strong>仅购汇环节就需要10年（单人），合并配偶额度也需5年</strong>——且不计算其他用汇需求。实际操作中，许多人通过”蚂蚁搬家”式分拆购汇、地下钱庄、或贸易项下虚报等方式完成资金出境——<strong>这些操作均存在合规风险，轻则罚款，重则涉及刑事追诉。</strong></p><p>这不是一个可以轻描淡写的”操作细节”，而是一个会直接决定策略是否可执行的<strong>硬约束</strong>。</p><h3 id="_11-4-汇率风险-二十年间6-0到8-3的大幅摆动" tabindex="-1">11.4 汇率风险：二十年间6.0到8.3的大幅摆动 <a class="header-anchor" href="#_11-4-汇率风险-二十年间6-0到8-3的大幅摆动" aria-label="Permalink to &quot;11.4 汇率风险：二十年间6.0到8.3的大幅摆动&quot;">​</a></h3><p>USD/CNY汇率在过去二十年间在6.0到8.3之间大幅摆动。假设你在汇率7.0时购入一套50万美元的房产（投入350万人民币），五年后以55万美元出售（账面盈利10%），但如果同期人民币升值至6.5，你换回的人民币只有357.5万元——<strong>扣除持有成本和交易费用后，实际亏损。</strong></p><p>汇率波动完全可以吞掉租售比优势。对于以人民币为收入基准、以美元计价持有资产的投资者来说，<strong>汇率风险是一个与房产收益同等量级的变量</strong>，不能忽略。</p><h3 id="_11-5-2008年阳光带房价腰斩的历史教训" tabindex="-1">11.5 2008年阳光带房价腰斩的历史教训 <a class="header-anchor" href="#_11-5-2008年阳光带房价腰斩的历史教训" aria-label="Permalink to &quot;11.5 2008年阳光带房价腰斩的历史教训&quot;">​</a></h3><p>我们推荐美国阳光带（佛州、德州）时引用了7%-9%的高租金回报率，但必须同时提醒：2008年金融危机中，佛州、亚利桑那、内华达等阳光带州房价腰斩——凤凰城峰谷跌幅约56%，拉斯维加斯约60%，迈阿密约50%。高租金回报率往往伴随着更高的价格波动风险——这是金融学的基本常识。</p><h3 id="_11-6-地缘政治尾部风险" tabindex="-1">11.6 地缘政治尾部风险 <a class="header-anchor" href="#_11-6-地缘政治尾部风险" aria-label="Permalink to &quot;11.6 地缘政治尾部风险&quot;">​</a></h3><p>中美关系的不确定性是另一个不可量化的尾部风险。资产冻结、投资限制、税务歧视——这些极端情景虽然概率低，但一旦发生，影响是毁灭性的。对于高净值人群，<strong>在任何单一国家持有过大比例的海外资产，本身就是一种风险集中</strong>。</p><h3 id="_11-7-修正后的策略适用条件" tabindex="-1">11.7 修正后的策略适用条件 <a class="header-anchor" href="#_11-7-修正后的策略适用条件" aria-label="Permalink to &quot;11.7 修正后的策略适用条件&quot;">​</a></h3><p>综合以上风险，”美国买房、中国租房”策略<strong>并非无条件成立</strong>。它的适用前提至少包括：</p><p>条件说明家庭年收入足够覆盖美国持有成本+汇率波动缓冲（建议年收入的30%以下用于海外房产持有）税务身份规划需要提前设计持有架构（信托、公司）以规避遗产税和FIRPTA资金出境合规性需要有合法的资金出境渠道，或接受漫长合规周期汇率风险承受力能承受20%-30%的汇率波动而不影响生活持有期限至少10年以上，以摊平交易成本和汇率波动资产集中度海外房产不应占家庭总资产的50%以上<strong>不满足上述条件的家庭，盲目执行”美国买房”策略，可能从一个坑跳进另一个坑。</strong> 这套策略的真正适用人群是：<strong>有合法外汇来源、有全球资产配置经验、有专业税务顾问支持的高净值家庭</strong>——而非普通中产。</p><h3 id="十二、策略修正-房产税落地后的最优配置" tabindex="-1">十二、策略修正：房产税落地后的最优配置 <a class="header-anchor" href="#十二、策略修正-房产税落地后的最优配置" aria-label="Permalink to &quot;十二、策略修正：房产税落地后的最优配置&quot;">​</a></h3><p>人群当前策略房产税落地后修正策略首套刚需中国租房，享受低持有成本不变——免征面积保护，持有成本几乎为零改善型家庭中国租房为主，可考虑持有一套微调——控制面积在免征线内，避免超额税负多套房投资者中国持有多套，以租养房重大调整——减持多余房产，转向美国等永久产权市场（前提见风险清单章）高净值人群中美双线配置强化全球配置——永久产权+明确税制+更高租售比美国赚钱中国花在中国消费人力服务不变——房产税不影响人力服务的本地定价优势<strong>房产税落地时点的情景分支：</strong></p><p>上述修正策略建立在”房产税终将全面落地”的假设上。但考虑到当前经济形势和财政收入结构，也存在两种替代情景：</p><ul><li><strong>情景A：未来五年内不落地，或仅局部试点不扩围。</strong> 当前策略基本不变。多套房持有者可继续持有，但应关注政策风向变化，做好随时调整的准备。人口下降对三四线城市的冲击不依赖于房产税是否落地——即使没有房产税，这些城市的房产也在持续贬值。</li><li><strong>情景B：局部试点扩围至新一批城市（如杭州、南京等）。</strong> 试点城市的二套房持有者应提前减持多余房产，尤其是三四线城市的投资性房产。但全面铺开仍需时间，不必恐慌性抛售。</li></ul><p><strong>核心原则：无论房产税何时落地，”把资产集中在人口流入、永久产权、高租售比的市场”这个方向不会改变。</strong></p><h3 id="十三、终极账本-70年持有成本对比" tabindex="-1">十三、终极账本：70年持有成本对比 <a class="header-anchor" href="#十三、终极账本-70年持有成本对比" aria-label="Permalink to &quot;十三、终极账本：70年持有成本对比&quot;">​</a></h3><p>以一套价值50万美元（约360万人民币）的房产为例，持有70年：</p><p>项目美国中国（无房产税）中国（房产税落地后·首套免征）中国（房产税落地后·二套全额计税）购房成本50万美元360万元（含地价）360万元（含地价）360万元（含地价）70年房产税累计35万-105万美元0元0元约106万元70年保险+维护+HOA约43万-137万美元约17-50万元约17-50万元约17-50万元70年持有成本合计（不含购房款）约78万-242万美元约17-50万元约17-50万元约123-156万元持有成本/房价156%-484%5%-14%5%-14%34%-43%<em>注：美国侧保险+维护+HOA数据——保险800-2,500美元/年 + 维护3,000-7,500美元/年 + 物业费/HOA 2,400-9,600美元/年，合计年支出6,200-19,600美元，×70年 = 43.4万-137.2万美元。中国侧物业维护按2,400-7,200元/年×70年 = 16.8万-50.4万元。二套全额计税年房产税按360万×70%×0.6%≈1.51万元/年×70年≈106万元计。以上持有成本均不含购房款。</em></p><p><strong>贴现计算假设与敏感性分析：</strong></p><p>以上为名义值简单加总，未做贴现。70年间每年的支出和今天的一次性支出不能直接加总。以下按年末等额支付假设，给出不同贴现率下的现值估算：</p><p><strong>美国：</strong> 年持有成本取中位值2万美元（房价的4%），70年期。</p><ul><li>3%贴现率：现值 ≈ 2万 × [1-(1.03)⁻⁷⁰]/0.03 ≈ 2万 × 29.0 ≈ <strong>58万美元（房价的116%）</strong></li><li>5%贴现率：现值 ≈ 2万 × [1-(1.05)⁻⁷⁰]/0.05 ≈ 2万 × 19.4 ≈ <strong>39万美元（房价的78%）</strong></li><li>取全区间1.1万-3.5万美元/年（均按3%贴现率）：对应现值约<strong>32万-102万美元（房价的64%-204%）</strong></li></ul><p><strong>中国（房产税落地后，分两支）：</strong></p><p><strong>支线一（首套/免征，仅物业维护）：</strong> 年持有成本0.24万-0.72万元（中位0.48万元），70年期。</p><ul><li>3%贴现率（中位0.48万）：0.48万 × 29.0 ≈ <strong>13.9万元（房价的3.9%）</strong></li><li>5%贴现率（中位0.48万）：0.48万 × 19.4 ≈ <strong>9.3万元（房价的2.6%）</strong></li><li>全区间（按3%贴现率）：约<strong>7万-21万元（房价的2%-6%）</strong></li></ul><p><strong>支线二（360万二套全额计税，年税约1.5万元）：</strong> 年持有成本约1.8万-2.2万元（中位2.0万元），70年期。</p><ul><li>3%贴现率（中位2.0万）：2.0万 × 29.0 ≈ <strong>58万元（房价的16%）</strong></li><li>5%贴现率（中位2.0万）：2.0万 × 19.4 ≈ <strong>38.8万元（房价的10.8%）</strong></li></ul><p><strong>结论：免征情景下，美国现值（房价的64%-204%）为中国（房价的2%-6%）的10-100倍，数量级差距成立；二套全额计税情景下，差距收窄至约4-15倍（中位口径约7倍：116%/16%、78%/10.8%；区间交叉极值3.6-14倍）——与第二章情景测算中”极端情况为美国的1/3到1/4”的口径衔接一致。”中国持有成本远低于美国”的命题不变；需要放弃的是”差距恒为数量级”的单一表述，改为按情景分层。</strong></p><h3 id="十四、谁最痛-免征结构的政治算术" tabindex="-1">十四、谁最痛：免征结构的政治算术 <a class="header-anchor" href="#十四、谁最痛-免征结构的政治算术" aria-label="Permalink to &quot;十四、谁最痛：免征结构的政治算术&quot;">​</a></h3><p>房产税落地后，最受伤的<strong>不是</strong>在中国租房的人，也<strong>不是</strong>在美国买房的人，而是<strong>在中国持有多套房产的投资者</strong>。</p><p>他们的处境是：</p><ul><li>购房时已经一次性支付了高额土地出让金（房价的40%-60%）</li><li>现在每年还要额外缴纳房产税</li><li>租金回报率仅1.5%，可能无法覆盖新增的持有成本</li><li>房价还在下跌通道中，资产缩水和税负增加同时发生</li><li>如果房产在三四线城市，可能面临”卖不掉、租不出、还要交税”的三重困境</li></ul><p><strong>这才是房产税的真正”杀伤力”——它不是对刚需加税，而是对多套房持有者加税。税制设计的免征结构，本质是一场政治算术：让刚需家庭继续享受与美国相差10-100倍的持有成本（支线一），以零税负换取社会接受度；同时让多套房持有者的持有成本相对支线一上升约4倍（支线二），承担真实税负以抑制投机。</strong> 用老百姓的话说：<strong>“买的时候剥了一层皮，持有的时候再剥一层皮。”</strong></p><h3 id="十五、蒂伯特定理——拱顶石的合龙" tabindex="-1">十五、蒂伯特定理——拱顶石的合龙 <a class="header-anchor" href="#十五、蒂伯特定理——拱顶石的合龙" aria-label="Permalink to &quot;十五、蒂伯特定理——拱顶石的合龙&quot;">​</a></h3><p>上篇用巴拉萨-萨缪尔森效应解释了商品市场的全球定价与本地定价之分，但它在公共服务面前停住了：商品可以全球套利，公共服务不能——那人们怎么办？</p><p>1956年，经济学家查尔斯·蒂伯特（Charles Tiebout）回答了这另一半问题。他的核心命题是：<strong>人们用脚投票。</strong> 当一个国家的公共服务由地方政府提供、而居民可以自由迁移时，每个人都会选择那个”税收-服务组合”最合意的城市定居。美国房产税，就是蒂伯特竞争的明码价签——你每年付的钱，买的是这个学区、这条警线、这条路。</p><p>中国的特殊性在于：公共服务同样地方化，却没有透明年费。它的价格被打进了一次性的房价里——学区房，就是市场在无透明年费机制下，自发为地方公共服务这个”蒂伯特商品”定出的价格；户口，则是这张终身会员卡的激活凭证。更准确地说，蒂伯特模型成立的前提是”人走，权利跟着走”；户口恰恰是”权利不跟着人走”的制度——你可以搬去深圳工作，但孩子的学位不跟着你走。这正是中国版用脚投票必须一次性买断、且溢价如此之高的深层原因。中国人也在用脚投票，但买的是一次性锁定、不可退换的年票。</p><p>从这个角度看，房产税从来不是”多一笔税”——它是价格机制的重构：把隐性价格显性化，把一次性价格年付化。所谓”地主变管家”，用蒂伯特的语言说，就是地方政府第一次要参与明码标价的竞争——不再是垄断卖地的地主，而是需要靠服务质量争夺纳税人-居民的管家。</p><p><strong>上篇的消费套利和下篇的房产税，至此合成了一颗完整的球：同一个人，在不同市场做同一件事——对价格信号做反应。</strong> 在可贸易品市场，他对全球价差做反应（美国买iPhone，中国点外卖）；在公共服务市场，他对税收-服务组合做反应（用脚投票，选择最优城市）。而结尾的”管家能否成立”也自动获得理论落点：取决于显性价格是否换来真实的用脚投票权——如果纳税人交了税却不能选择离开、不能要求服务改善，那”管家”就只是换了标签的地主。</p><blockquote><p>让我们回到最初那个问题：已经一次性收了70年的地租，再开征房产税，到底有没有合法性？<br> 法理上，官方已经给出了自洽的答案——”地租是地租，税是税，租税并行不矛盾”。但从实质公平来看，这个答案能否说服每一个已经掏空六个钱包、一次性预缴了70年”地租”的家庭，是另一回事。<br> 真正值得关注的，不是合法性争论本身，而是这场争论背后正在发生的一个更深层的转变：<strong>中国的地方政府，正在从”卖地的地主”变成”收税的管家”。</strong> 地主靠一次性卖地赚钱，管家靠持续提供服务收费。这个转变如果成功，房产税就不只是一笔新的负担，而可能成为纳税人与政府之间建立”对价关系”的起点——你交税，你要求服务，你监督支出。<br> 但这不是自动成立的。加州1978年通过Prop 13冻结基础税率后，学区财政从本地财产税转向州拨款，但教育质量分化并未消失，而是以社区补充捐款和Mello-Roos特别税区的形式重新固化——<strong>“房产税→好治理”不是物理定律，它需要透明度机制、纳税人表达渠道和公共服务问责制度作为前提。</strong> 没有这些前提，房产税就只是”又一笔不知道花在哪的钱”。<br> “管家”能否真正成立，取决于一个核心条件：纳税人是否有制度化的渠道要求公共服务对价。在美国，这个渠道是地方议会选举、学区委员会投票、房产税公投——Prop 13本身就是纳税人通过投票限制税率的产物。在中国，这个渠道是否正在形成、以什么形态形成、能否承载”纳税人监督”的功能，是一个远比房产税本身更复杂的治理命题。本文无力回答这个问题，但必须坦承：如果没有这个前提，”管家”就只是换了一种收钱方式的地主——鹅城的故事就真的没有写完。<br> 70年后，土地归还国家，房子还在。但到那时候，决定这套房子值多少钱的，或许不再是它绑定了哪个学区、哪个户口，而是这个社区在过去几十年里，有没有用纳税人的钱，修好门口的路、建好旁边的学校、维护好楼下的公园。<br><strong>鹅城的故事还没有写完。黄四郎换了一件衣服，但收税的手没有变——至少在纳税人学会问”我的钱花在哪了”之前。</strong></p></blockquote><hr><blockquote><p>本文同步自知乎，<a href="https://zhuanlan.zhihu.com/p/2084661184180049604" target="_blank" rel="noreferrer">查看原文</a></p></blockquote>',192)])])}const c=o(s,[["render",e]]);export{u as __pageData,c as default};
